package dev.mlua.common.mixin;

import java.util.Map;

/** Resolver backed by the official-to-runtime method mapping generated by Gradle. */
public final class MLuaGeneratedMappingResolver implements MLuaMappingResolver {
   private final String loaderId;
   private final Map<String, Map<String, String>> methodMappings;

   public MLuaGeneratedMappingResolver(String loaderId) {
      this.loaderId = loaderId == null || loaderId.isBlank() ? "unknown" : loaderId;
      this.methodMappings = loadMappings();
   }

   @Override
   public String loaderId() {
      return loaderId;
   }

   @Override
   public ResolvedMethod mapMethod(String owner, String method, String descriptor) {
      String mapped = MLuaMixinMapping.resolveMethodName(owner, method, descriptor, methodMappings);
      String runtimeMethod = mapped == null ? method : mapped;
      return new ResolvedMethod(owner, runtimeMethod, descriptor);
   }

   @Override
   public String mapRedirectTarget(String target) {
      return MLuaMixinMapping.resolveInvocationTarget(target, methodMappings);
   }

   private Map<String, Map<String, String>> loadMappings() {
      return MLuaMixinMapping.load(MLuaGeneratedMappingResolver.class.getClassLoader());
   }
}
